useEffect(() => {
    if (
        // We only want to clear selected transactions when a transaction is deleted, not when it's updated.
        // We can heuristic this by checking if the number of transactions has decreased.
        Object.keys(transactions ?? {}).length >= Object.keys(previousTransactions ?? {}).length ||
        // If the user is on another page, we don't want to clear the selection.
        navigation.isFocused()
    ) {
        return;
    }
    clearSelectedTransactions();
    // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
}, [previousTransactions, transactions, clearSelectedTransactions]);

